  --color-bg: #f8f8fa;
  --color-surface: #ffffff;
  --color-border: #e2e2e8;
  --color-text: #1a1a2e;
  --color-text-muted: #6b6b80;
  --color-primary: #4f46e5;
  --color-primary-hover: #4338ca;
  --color-danger: #dc2626;
  --color-danger-hover: #b91c1c;
  --color-danger-bg: #fef2f2;
  --color-focus: #4f46e5;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.10), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 20px 40px rgba(0,0,0,.14), 0 8px 16px rgba(0,0,0,.08);
  --transition: 150ms ease;
}

html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  min-height: 100vh;
}

/* ── Utilities ── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  background: var(--color-primary);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Focus styles ── */
:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

/* ── Header ── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: .875rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-text);
  text-decoration: none;
  white-space: nowrap;
}
.logo:hover { color: var(--color-primary); }

.breadcrumb {
  list-style: none;
  display: flex;
  align-items: center;
  gap: .375rem;
  font-size: .875rem;
  color: var(--color-text-muted);
  flex-wrap: wrap;
}
.breadcrumb a {
  color: var(--color-text-muted);
  text-decoration: none;
}
.breadcrumb a:hover { color: var(--color-primary); text-decoration: underline; }
.breadcrumb [aria-current="page"] { color: var(--color-text); font-weight: 500; }

/* ── Main layout ── */
.main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

.preview-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 1.5rem;
  align-items: start;
}

@media (max-width: 768px) {
  .preview-layout { grid-template-columns: 1fr; }
}

/* ── Image preview ── */
.image-wrapper {
  background: #0d0d12;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 4/3;
}
.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ── Details sidebar ── */
.image-details {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.image-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  word-break: break-all;
}

.meta-list {
  display: flex;
  flex-direction: column;
  gap: .625rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--color-border);
}
.meta-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-size: .875rem;
}
.meta-row dt { color: var(--color-text-muted); }
.meta-row dd { font-weight: 500; text-align: right; }

/* ── Buttons ── */
.action-group {
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .625rem 1rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  line-height: 1;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  width: 100%;
  white-space: nowrap;
}

.btn-secondary {
  background: var(--color-bg);
  border-color: var(--color-border);
  color: var(--color-text);
}
.btn-secondary:hover {
  background: #ebebef;
  border-color: #c8c8d4;
}

.btn-danger {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: #fff;
}
.btn-danger:hover {
  background: var(--color-danger-hover);
  border-color: var(--color-danger-hover);
}

/* ── Dialog ── */
dialog {
  padding: 0;
  border: none;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
  background: var(--color-surface);
  /* closed state is handled by the browser; no custom hidden styles needed */
}

dialog::backdrop {
  background: rgba(10, 10, 20, .55);
  backdrop-filter: blur(2px);
}

.dialog-inner {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
}

.dialog-icon {
  width: 60px; height: 60px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-danger);
  flex-shrink: 0;
}

.dialog-heading {
  font-size: 1.25rem;
  font-weight: 700;
}

.dialog-description {
  font-size: .9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  max-width: 320px;
}
.dialog-description strong { color: var(--color-text); }

.dialog-actions {
  display: flex;
  gap: .75rem;
  width: 100%;
  margin-top: .5rem;
}
.dialog-actions .btn {
  flex: 1;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

/* ── Forced colors (high contrast mode) ── */
@media (forced-colors: active) {
  .btn { border: 1px solid ButtonText; }
  .btn-danger { forced-color-adjust: none; background: LinkText; color: Canvas; border-color: LinkText; }
  .btn-danger:hover { background: ActiveText; border-color: ActiveText; }
  dialog { border: 1px solid CanvasText; }
  .dialog-icon { border: 2px solid CanvasText; }
}

/* ── Narrow viewport reflow (320 px) ── */
@media (max-width: 360px) {
  .header-inner { padding: .75rem 1rem; }
  .main { padding: 1rem .75rem 3rem; }
  .dialog-inner { padding: 1.25rem; }
  .dialog-actions { flex-direction: column; }
}
