const { chromium } = require("playwright");
const path = require("path");
const fs = require("fs");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const fileUrl = "file://" + path.resolve("index.html");
  await page.goto(fileUrl, { waitUntil: "load" });
  await page.addScriptTag({ path: "/tmp/axe.min.js" });

  // Test 1: page in default (closed dialog) state
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Test 2: open the dialog and re-run
  await page.click("#delete-trigger");
  await page.waitForSelector("dialog[open]");
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  const fmt = (v) => ({ id: v.id, impact: v.impact, tags: v.tags.filter(t => t.startsWith("wcag") || t === "best-practice"), targets: v.nodes.map(n => n.target) });
  const result = {
    closed: { wcag: r1.violations.filter(v => !v.tags.includes("best-practice")).map(fmt), bp: r1.violations.filter(v => v.tags.includes("best-practice")).map(fmt) },
    open:   { wcag: r2.violations.filter(v => !v.tags.includes("best-practice")).map(fmt), bp: r2.violations.filter(v => v.tags.includes("best-practice")).map(fmt) }
  };
  process.stdout.write(JSON.stringify(result, null, 2));
  process.exit(result.closed.wcag.length + result.open.wcag.length > 0 ? 1 : 0);
})();
EOF
